(* [comment removed for export] *)
Definition mssC_post (sp gp tp s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (S r ioc lo : Z) (j0 : list byte) (s3v s2v s1v s0v rav : word) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m',
    ms' = MS (mkR (Z_to_bv 64 P_A_MSS_RET3) (Z_to_bv 64 (bv_unsigned sp + -64)) gp tp t0 t1 t2
                  (Z_to_bv 64 r) (Z_to_bv 64 S) (Z_to_bv 64 r) (Z_to_bv 64 (bv_unsigned sp + -56)) (Z_to_bv 64 S) a3 a4 a5 a6 a7
                  (Z_to_bv 64 (S + 40)) (Z_to_bv 64 (Z.shiftr (S + 40) 3 + 2147450880)) s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (Z_to_bv 64 P_A_DO_ADD_SERVICE) fc None m' (seg_rom asegs)
    /\ munch [(bv_unsigned sp + -128, bv_unsigned sp); (S + 40, S + 48)]%Z m m' /\ wmono asegs m m' /\ mem_inv asegs m'
    /\ stk asegs m' lo (bv_unsigned sp + -64)
    /\ rw_cells asegs m' (bv_unsigned sp + -64) (mss_frame j0 (Z_to_bv 64 AL_TYPEID_SCHED) (C8 (Z_to_bv 64 0)) s3v s2v s1v s0v rav)
    /\ rw_cells asegs m' S (SvcHdrCells (mkSVC AVP_SCHED 0 0 ioc 0 P_A_DESTROY_ALLOC_SCHED)).

Lemma mssC : forall (pcv sp gp tp t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 s3x s4x s5x s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word)
    (s3v s2v s1v s0v rav s5 s4 s2 s1 : word) (F : bvmap 5 word) fc (m : mem) (S r ioc allocb ownp lo : Z) (j0 j16 j0' : list byte),
  (pcv = Z_to_bv 64 P_A_MSS_RET2 \/ pcv = ret_pc (Z_to_bv 64 P_A_MSS_RET2)) ->
  rw_cells asegs m (bv_unsigned sp + -64) (mss_frame j0 (Z_to_bv 64 allocb) (CB 8 j16) s3v s2v s1v s0v rav) ->
  rw_cells asegs m (bv_unsigned sp + -128) (aos_frame j0' s5 s4 s2 s1 r) ->
  rw_cells asegs m S (SvcHdrCells (mkSVC AVP_SCHED 0 0 ioc 0 0)) -> rblock_range S NEWSZ_SCH -> addressable m S NEWSZ_SCH ->
  0 <= ioc < 2^64 ->
  stk asegs m lo (bv_unsigned sp + -128) -> lo + 128 <= bv_unsigned sp -> aceil <= lo ->
  mem_inv asegs m ->
  evt asegs (mssC_post sp gp tp s4 s5 s6 s7 s8 s9 s10 s11 F fc S r ioc lo j0 s3v s2v s1v s0v rav m)
    (MS (mkR pcv (Z_to_bv 64 (bv_unsigned sp + -128)) gp tp t0 t1 t2
             (Z_to_bv 64 allocb) (Z_to_bv 64 ownp) a0 a1 a2 a3 a4 a5 a6 a7
             (Z_to_bv 64 S) s3x s4x s5x s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
